// Managed group record: create / edit / archive / delete.
// Publishing lives on Publish to. id = "new" creates a group.
import React, { useEffect, useState } from 'react';
import { Text, View } from 'react-native';
import { router, Stack, useLocalSearchParams } from 'expo-router';
import { useConfirmDelete } from '../../../components/confirm-sheet';
import { NotFound, useCanModerate } from '../../../components/mod';
import { DeleteGroupSheet } from '../../../components/delete-group-sheet';
import { ActionRow, CoverBand, EntityTitle } from '../../../components/record-chrome';
import { GroupPublishList } from '../../../components/group-publish';
import { GroupSponsors } from '../../../components/group-sponsors';
import { MeetupProConnect } from '../../../components/MeetupLink';
import { BackChevron, Button, EmptyState, ErrorText, Field, FieldGrid, Page, SectionCard, StatusPill, styles } from '../../../components/ui';
import { meetupGroupsForPro } from '../../../lib/meetup-url';
import { isGroupSlug, normalizeGroupSlug } from '../../../lib/group-views';
import { deleteGroup, getGroup, saveGroup, setGroupArchived } from '../../../lib/groups';
import { safeMeetupUrl } from '../../../lib/publications';
import { fmtDate } from '../../../lib/format';
import { OwnerFace } from '../../../components/owner-face';
import { useOwnerProfile } from '../../../lib/owner-label';
import { flash } from '../../../lib/flash';
import { fs } from '../../../lib/theme';
import type { ClubGroup } from '../../../lib/types';

function MeetupProSection({ group }: { group: ClubGroup }) {
  const proGroups = meetupGroupsForPro([group], group.owner_id ?? null, true);
  return (
    <SectionCard title="Meetup Pro">
      {proGroups.length ? <MeetupProConnect groups={proGroups} /> : (
        <Text style={[styles.muted, { fontSize: fs(13) }]}>Add a meetup.com group URL and save it before connecting Meetup Pro for this group.</Text>
      )}
    </SectionCard>
  );
}

type Form = { name: string; slug: string; description: string; locality: string; image_url: string; meetup_url: string };
const blank: Form = { name: '', slug: '', description: '', locality: '', image_url: '', meetup_url: '' };
const toForm = (g: ClubGroup): Form => ({
  name: g.name, slug: g.slug, description: g.description, locality: g.locality ?? '', image_url: g.image_url ?? '', meetup_url: g.meetup_url ?? '',
});

export default function ManageGroup() {
  const { id } = useLocalSearchParams<{ id: string }>();
  const isNew = id === 'new';
  const { ready, ok } = useCanModerate();
  const [group, setGroup] = useState<ClubGroup | null | undefined>(isNew ? null : undefined);
  const [form, setForm] = useState<Form>(blank);
  const [slugTouched, setSlugTouched] = useState(false);
  const [err, setErr] = useState<string | null>(null);
  const [note, setNote] = useState<string | null>(null);
  const [busy, setBusy] = useState<string | null>(null);
  const removeSheet = useConfirmDelete();
  const owner = useOwnerProfile(group?.owner_id, !!group);

  const reload = async () => {
    const row = await getGroup(id!);
    setGroup(row);
    if (row) setForm(toForm(row));
  };
  useEffect(() => { if (ok && !isNew) reload().catch((e) => setErr(e.message)); }, [ok, id]);

  if (!ready) return <View style={{ flex: 1 }} />;
  if (!ok) return <NotFound />;
  if (!isNew && group === null) return <Page><BackChevron fallback="/groups" /><EmptyState title="Group not found" /></Page>;

  const run = async (label: string, fn: () => Promise<string | void>) => {
    setBusy(label); setErr(null); setNote(null);
    try { const n = await fn(); if (n) setNote(n); } catch (e: any) { setErr(e.message); } finally { setBusy(null); }
  };
  const save = () => run('save', async () => {
    const name = form.name.trim();
    if (!name) throw new Error('Name is required.');
    const slug = normalizeGroupSlug(form.slug || name);
    if (!isGroupSlug(slug)) throw new Error('Web address needs at least two letters or numbers.');
    const meetup = form.meetup_url.trim();
    if (meetup && !safeMeetupUrl(meetup)) throw new Error('Meetup URL must be an https link on meetup.com.');
    const image = form.image_url.trim();
    if (image && !/^https:\/\//i.test(image)) throw new Error('Cover image must be an https URL.');
    const input = {
      name, slug, description: form.description.trim(), locality: form.locality.trim() || null,
      image_url: image || null, meetup_url: meetup || null,
    };
    const newId = await saveGroup(input, isNew ? undefined : id);
    if (isNew) { router.replace(`/groups/manage/${newId}`); return; }
    await reload();
    return 'Saved. Meetup and the public page stay as they are until you publish.';
  });
  const archive = () => run('archive', async () => {
    if (!group) return;
    await setGroupArchived(group.id, !group.archived);
    await reload();
    return group.archived ? 'Restored.' : 'Archived — hidden from members. The public page is off.';
  });
  const remove = () => {
    if (!group) return;
    setErr(null);
    removeSheet.run(async () => {
      await deleteGroup(group.id);
      flash('Group deleted');
      router.replace('/groups');
    });
  };
  const set = (k: keyof Form) => (t: string) => {
    if (k === 'name' && !slugTouched && isNew) setForm({ ...form, name: t, slug: normalizeGroupSlug(t) });
    else {
      if (k === 'slug') setSlugTouched(true);
      setForm({ ...form, [k]: t });
    }
  };

  return (
    <Page>
      <Stack.Screen options={{ title: isNew ? 'New group' : group?.name ?? 'Group', headerShown: false }} />
      <BackChevron fallback={isNew || !id ? '/groups' : `/groups/${id}`} />
      {isNew ? <EntityTitle title="New group" meta="Create a club group. Nothing goes to Meetup or the public page until you publish it." />
        : group ? <>
          <CoverBand url={group.image_url} />
          <EntityTitle title={group.name} meta={group.locality} pills={<StatusPill label={group.archived ? 'Archived' : 'Active'} tone={group.archived ? 'default' : 'success'} />} />
          <ActionRow>
            <Button small variant="neutral" icon="eye-outline" title="View" onPress={() => router.push(`/groups/${group.id}`)} />
            <Button small variant="neutral" icon="archive-outline" title={group.archived ? 'Unarchive' : 'Archive'} loading={busy === 'archive'} onPress={archive} />
            <Button small variant="danger" icon="trash-outline" title="Delete" onPress={removeSheet.ask} />
          </ActionRow>
          <FieldGrid fields={[['City', group.locality ?? '—'], ['Updated', fmtDate(group.updated_at)], ...(owner ? [['Owner', <OwnerFace profile={owner} />] as [string, React.ReactNode]] : [])]} />
        </> : null}
      <ErrorText>{err}</ErrorText>
      {note ? <Text style={[styles.muted, { fontSize: fs(13) }]}>{note}</Text> : null}
      <SectionCard title={isNew ? 'Details' : 'Edit details'}>
        <Field label="Name" value={form.name} onChangeText={set('name')} maxLength={160} />
        <Field label="Web address" help="Public page /g/this-address. Letters, numbers, and hyphens." value={form.slug} onChangeText={set('slug')} autoCapitalize="none" autoCorrect={false} maxLength={80} />
        <Field label="About" value={form.description} onChangeText={set('description')} multiline />
        <Field label="City" placeholder="New York, NY" value={form.locality} onChangeText={set('locality')} />
        <Field label="Cover image URL" help="https link. Shown on the group, like an event cover." value={form.image_url} onChangeText={set('image_url')} autoCapitalize="none" autoCorrect={false} />
        <Field label="Meetup URL" help="The existing Meetup group. Publishing records this link. It does not import Meetup’s member count." value={form.meetup_url} onChangeText={set('meetup_url')} autoCapitalize="none" autoCorrect={false} />
        <View style={{ flexDirection: 'row', gap: 8 }}>
          <Button title={isNew ? 'Create group' : 'Save'} onPress={save} loading={busy === 'save'} />
          <Button variant="neutral" title="Cancel" onPress={() => (router.canGoBack() ? router.back() : router.replace('/groups'))} />
        </View>
      </SectionCard>
      {group ? <GroupSponsors groupId={group.id} /> : null}
      {group ? <MeetupProSection group={group} /> : null}
      {group ? <GroupPublishList group={group} /> : null}
      {group ? <DeleteGroupSheet visible={removeSheet.open} busy={removeSheet.busy} error={removeSheet.error}
        onCancel={removeSheet.cancel}
        onConfirm={remove} /> : null}
    </Page>
  );
}
